/// Every [`SUPPORT_SPLICED_DOCS`] path, read from disk, paired with what it
/// would become after splicing `support_url` into its `<!-- support:
/// start/end -->` section(s) -- the one function both [`run`] and
/// `tests/support_ac05_*` call, so the two can never disagree on what
/// "spliced" means.
fn support_spliced_docs(support_url: Option<&str>) -> std::io::Result<Vec<(&'static str, String, String)>> {
    SUPPORT_SPLICED_DOCS
        .iter()
        .map(|&path| {
            let current = std::fs::read_to_string(path)?;
            let spliced = help::splice_support_section(&current, support_url);
            Ok((path, current, spliced))
        })
        .collect()
}

/// requirement 4: `host.<family>.<verb>` -> `family`; `billing.<verb>` ->
/// `"billing"`; `signup` (and any other bare, dot-less name) ->
/// `"(top-level)"`. Pure string slicing over `docs/tool-naming.md`'s own
/// rule -- never a second hand-maintained family list.
fn family_of(name: &str) -> &str {
    if let Some(rest) = name.strip_prefix("host.") {
        rest.split_once('.').map_or("(top-level)", |(family, _)| family)
    } else if name.starts_with("billing.") {
        "billing"
    } else {
        "(top-level)"
    }
}

/// requirement 4's own table: one row per canonical tool (`signup` plus
/// every [`crate::handler::host_tool_descriptors`] entry that isn't
/// itself a registered alias), with its family, any deprecated aliases
/// still pointing at it, and its description.
pub fn render_tools_markdown(kinds: &KindRegistry) -> String {
    let alias_names: HashSet<&str> = tool_aliases::TOOL_ALIASES.iter().map(|a| a.alias).collect();
    let mut tools = crate::handler::host_tool_descriptors(kinds);
    tools.push(crate::handler::signup_tool());
    let canonical: HashSet<String> = crate::handler::canonical_control_plane_names(kinds).into_iter().collect();
    tools.retain(|t| !alias_names.contains(t.name.as_ref()) && (canonical.contains(t.name.as_ref()) || t.name == "signup"));
    tools.sort_by(|a, b| a.name.cmp(&b.name));

    let mut out = String::new();
    out.push_str("# Tools\n\n");
    out.push_str(
        "Generated by `mcphost gen-docs` from the live `host.*`/`billing.*`/`signup` \
         registry -- canonical name, family, description, and any deprecated aliases \
         still working for it. See `docs/tool-naming.md` for the naming rule and how \
         aliases/deprecation work. Each row's schema is the generated section in \
         `www/llms-full.txt` (link in the last column). Do not hand-edit; run `mcphost gen-docs` after \
         registering or renaming a tool instead.\n\n",
    );
    out.push_str("| canonical | family | aliases | description | schema |\n");
    out.push_str("|---|---|---|---|---|\n");
    for t in &tools {
        let family = family_of(&t.name);
        // Deprecated aliases, then the flattened `a_b_c` form -- every other
        // name `tools/list` advertises for this tool.
        let mut names: Vec<String> = tool_aliases::aliases_of(&t.name).into_iter().map(String::from).collect();
        names.extend(tool_aliases::flattened_form(&t.name));
        let aliases = names.join(", ");
        let description = t
            .description
            .clone()
            .unwrap_or_default()
            .replace('|', "\\|")
            .replace('\n', " ");
        // PRD-mcphost-llms-full-generated-from-schemas R6: an index row, not
        // a second schema copy -- the schema lives in the generated section.
        let slug = crate::llms_txt::anchor_slug(&t.name);
        out.push_str(&format!(
            "| `{}` | {family} | {aliases} | {description} | [schema](www/llms-full.txt#{slug}) |\n",
            t.name
        ));
    }
    out.push_str(ARCHIVE_LAYOUT_HEADING);
    out.push_str(
        "\nEvery `host.export` archive is a `.tar.gz` of exactly these entries, and \
         `host.import` accepts exactly these. Generated from `export::ArchiveEntry`.\n\n",
    );
    out.push_str("| path | host.import |\n|---|---|\n");
    for (pattern, note) in crate::export::ArchiveEntry::layout() {
        out.push_str(&format!("| `{pattern}` | {note} |\n"));
    }
    // PRD-mcphost-contract-output-schemas R7: one `Returns` block per tool,
    // rendered from the same `output_schema` the contract and `tools/list`
    // carry.
    out.push_str("\n## Returns\n\n");
    out.push_str(
        "Top-level fields of each tool's `structuredContent`, from its `output_schema` \
         (`contracts/host-output-schemas.v1.json`). \"always\" marks a field every captured \
         response carried.\n",
    );
    for t in &tools {
        let Some(schema) = &t.output_schema else { continue };
        out.push_str(&format!("\n### `{}`\n\n**Returns**\n\n", t.name));
        out.push_str(&render_returns_block(schema));
    }
    out
}

/// The bullet list of an `output_schema`'s top-level properties, sorted by
/// name: `` - `field`: type (always) ``.
fn render_returns_block(schema: &serde_json::Map<String, serde_json::Value>) -> String {
    fn type_label(schema: &serde_json::Value) -> String {
        let one = |t: &str| -> String {
            match (t, schema.get("items").and_then(|i| i.get("type"))) {
                ("array", Some(item)) => format!("array<{}>", type_label_of(item)),
                _ => t.to_string(),
            }
        };
        match schema.get("type") {
            Some(serde_json::Value::String(t)) => one(t),
            Some(serde_json::Value::Array(ts)) => {
                ts.iter().filter_map(|t| t.as_str()).map(one).collect::<Vec<_>>().join(" | ")
            }
            _ => "any".to_string(),
        }
    }
    fn type_label_of(t: &serde_json::Value) -> String {
        match t {
            serde_json::Value::String(s) => s.clone(),
            serde_json::Value::Array(ts) => ts.iter().filter_map(|t| t.as_str()).collect::<Vec<_>>().join(" | "),
            _ => "any".to_string(),
        }
    }
    let required: HashSet<&str> = schema
        .get("required")
        .and_then(|r| r.as_array())
        .map(|r| r.iter().filter_map(|v| v.as_str()).collect())
        .unwrap_or_default();
    let mut out = String::new();
    if let Some(props) = schema.get("properties").and_then(|p| p.as_object()) {
        for (name, prop) in props {
            let always = if required.contains(name.as_str()) { " (always)" } else { "" };
            out.push_str(&format!("- `{name}`: {}{always}\n", type_label(prop)));
        }
    }
    if out.is_empty() {
        out.push_str("- (no fields declared)\n");
    }
    out
}

/// PRD-mcphost-blob-virus-and-type-guard R8: the accepted-types table,
/// rendered from [`crate::blobs::BLOB_TYPES`] so it cannot name a type the
/// host refuses.
pub fn render_blob_types_table() -> String {
    let mut out = String::from("| mime | extensions | active content |\n|---|---|---|\n");
    for t in crate::blobs::BLOB_TYPES {
        let exts = t.extensions.iter().map(|e| format!(".{e}")).collect::<Vec<_>>().join(" ");
        out.push_str(&format!("| `{}` | {exts} | {} |\n", t.mime, if t.active_content { "yes" } else { "no" }));
    }
    out
}

/// The whole `docs/blob-types.md`: a header plus [`render_blob_types_table`].
pub fn render_blob_types_doc() -> String {
    format!(
        "# Accepted upload types\n\nGENERATED by `mcphost gen-docs` from `BLOB_TYPES` in `src/blobs.rs` -- do not edit by hand.\nAn upload link accepts these types; types with active content are refused unless the link sets `allow_active: true`.\n\n{}",
        render_blob_types_table()
    )
}

/// The heading `docs/tools.md`'s archive-layout table sits under.
pub const ARCHIVE_LAYOUT_HEADING: &str = "\n## Archive layout\n";

/// Writes (or, under `check`, diffs without writing) `docs/plans.md`,
/// `www/plans.html`, `docs/tools.md`, and -- AC5's build-time half -- the
/// `<!-- support: start/end -->` sections of [`SUPPORT_SPLICED_DOCS`],
/// relative to the current directory -- same convention as
/// `Command::LlmsTxt`'s own `check`/write split. Returns `Ok(true)` iff
/// anything was stale (meaningful only under `check`; under write it
/// always returns `Ok(false)`, nothing left for the caller to act on).
pub fn run(check: bool, kinds: &KindRegistry) -> std::io::Result<bool> {
    let mut stale = run_kind_contracts(check)?;
    let catalog = PlanCatalog::default_catalog();
    let support_url = std::env::var("MCPHOST_SUPPORT_URL").ok();
    let mut support_docs = support_spliced_docs(support_url.as_deref())?;
    // PRD-mcphost-client-install-links P0 requirement 4 (AC4): README also
    // carries `<!-- install-links:start/end -->`, a second, disjoint
    // marker pair in the SAME file the support splice above just touched
    // -- chained onto that splice's own output (not re-read from disk), so
    // this function's one write to README.md below carries both splices'
    // effects rather than one clobbering the other.
    for (path, _current, spliced) in &mut support_docs {
        if *path == "README.md" || *path == "www/llms.txt" {
            *spliced = crate::install_links::splice_install_links_section(
                spliced.as_str(),
                crate::install_links::CANONICAL_PUBLIC_URL,
            );
        }
    }

    for (path, rendered) in [
        (Path::new(PLANS_DOC_PATH), render_plans_markdown(&catalog)),
        (Path::new(PLANS_HTML_PATH), render_plans_html()),
        (Path::new(TOOLS_DOC_PATH), render_tools_markdown(kinds)),
        (Path::new(BLOB_TYPES_DOC_PATH), render_blob_types_doc()),
        (Path::new(crate::events::EVENTS_DOC_PATH), crate::events::render_events_doc()),
        (Path::new(crate::events::EVENTS_JSON_PATH), crate::events::render_event_kinds_json()),
        (Path::new(RETRIEVAL_DOC_PATH), crate::index::render_retrieval_doc()),
        (
            Path::new(INSTALL_DOC_PATH),
            crate::install_links::render_install_doc(crate::install_links::CANONICAL_PUBLIC_URL),
        ),
        (
            Path::new(INSTALL_DOC_WWW_PATH),
            crate::install_links::render_install_doc(crate::install_links::CANONICAL_PUBLIC_URL),
        ),
    ] {
        if check {
            let current = std::fs::read_to_string(path).unwrap_or_default();
            if current != rendered {
                eprintln!("gen-docs --check: {} is stale (run `mcphost gen-docs`)", path.display());
                stale = true;
            }
        } else {
            std::fs::write(path, rendered)?;
        }
    }

    if check {
        for (path, current, spliced) in &support_docs {
            if current != spliced {
                eprintln!("gen-docs --check: {path} is stale (run `mcphost gen-docs`)");
                stale = true;
            }
        }
    } else {
        for (path, _current, spliced) in &support_docs {
            std::fs::write(path, spliced)?;
        }
    }
    Ok(stale)
}

// ---- `gen-docs kinds` (PRD-mcphost-kind-docs-from-registry) ----

/// Where each kind's page lives, relative to the repo root.
pub const KIND_PAGES_DIR: &str = "docs/kinds";

/// The generated blocks of a kind page, in page order. Each is wrapped in
/// `<!-- <name>:start -->` / `<!-- <name>:end -->`.
pub const KIND_BLOCKS: [&str; 4] = ["kind-fields", "kind-ceilings", "kind-errors", "kind-example"];

fn escape_cell(text: &str) -> String {
    text.replace('|', "\\|").replace('\n', " ")
}

/// One block's body (markers excluded) rendered from `doc`.
pub fn render_kind_block(doc: &KindDoc, block: &str) -> String {
    match block {
        "kind-fields" => {
            let mut out = String::from("| field | type | required | meaning |\n|---|---|---|---|\n");
            for f in &doc.spec_fields {
                out.push_str(&format!(
                    "| `{}` | {} | {} | {} |\n",
                    f.name,
                    escape_cell(&f.ty),
                    if f.required { "yes" } else { "no" },
                    escape_cell(&f.meaning)
                ));
            }
            out
        }
        "kind-ceilings" if doc.ceilings.is_empty() => {
            "No plan ceiling bounds a call to this kind.\n".to_string()
        }
        "kind-ceilings" => {
            let mut out = String::from("| ceiling | free | pro |\n|---|---|---|\n");
            for c in &doc.ceilings {
                out.push_str(&format!("| `{}` | {} | {} |\n", c.field, c.free, c.pro));
            }
            out
        }
        "kind-errors" if doc.error_codes.is_empty() => {
            "This kind returns no kind-specific error codes.\n".to_string()
        }
        "kind-errors" => {
            let mut out = String::from("| code | when |\n|---|---|\n");
            for e in &doc.error_codes {
                out.push_str(&format!("| `{}` | {} |\n", e.code, escape_cell(&e.when)));
            }
            out
        }
        "kind-example" => format!(
            "```json\n{}\n```\n",
            serde_json::to_string_pretty(&doc.example).unwrap_or_default()
        ),
        other => unreachable!("unknown kind block {other}"),
    }
}

fn block_markers(block: &str) -> (String, String) {
    (format!("<!-- {block}:start -->"), format!("<!-- {block}:end -->"))
}

fn block_heading(block: &str) -> &'static str {
    match block {
        "kind-fields" => "Spec fields",
        "kind-ceilings" => "Kind ceilings",
        "kind-errors" => "Error codes",
        _ => "Canonical example",
    }
}

/// The page text with `block`'s marked region set to `body`; a page with no
/// markers for it gets the section appended (generated tail of the page).
fn splice_kind_block(page: &str, block: &str, body: &str) -> String {
    let (start, end) = block_markers(block);
    if let (Some(s), Some(e)) = (page.find(&start), page.find(&end))
        && s < e
    {
        return format!("{}{start}\n{body}{}", &page[..s], &page[e..]);
    }
    let mut out = page.trim_end().to_string();
    out.push_str(&format!("\n\n## {}\n\n{start}\n{body}{end}\n", block_heading(block)));
    out
}

/// One page block that differs from what the registry renders.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct StaleBlock {
    pub page: String,
    pub block: &'static str,
}

impl std::fmt::Display for StaleBlock {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        write!(f, "{} block {} is stale (run `mcphost gen-docs kinds --write`)", self.page, self.block)
    }
}

/// Renders every registered kind's generated blocks into
/// `<root>/docs/kinds/<kind>.md`. Under `write` the pages are rewritten;
/// either way the stale blocks (as found, before any write) are returned.
pub fn run_kinds(
    root: &Path,
    kinds: &KindRegistry,
    plans: &PlanCatalog,
    write: bool,
) -> std::io::Result<Vec<StaleBlock>> {
    let mut stale = Vec::new();
    for name in kinds.names() {
        let Some(kind) = kinds.get(name) else { continue };
        let doc = kind.doc(plans);
        let page_rel = format!("{KIND_PAGES_DIR}/{name}.md");
        let path = root.join(&page_rel);
        let current = std::fs::read_to_string(&path).unwrap_or_default();
        let mut next = current.clone();
        for block in KIND_BLOCKS {
            let body = render_kind_block(&doc, block);
            let spliced = splice_kind_block(&next, block, &body);
            if spliced != next {
                stale.push(StaleBlock { page: page_rel.clone(), block });
            }
            next = spliced;
        }
        if write && next != current {
            std::fs::write(&path, next)?;
        }
    }
    Ok(stale)
}

/// PRD-mcphost-kind-contract-conformance-generated-b R5: the `## Contract`
/// block of every `docs/kinds/<kind>.md`, rendered from the kind's
/// [`crate::kinds::contract::KindContract`] over the production kind set.
/// Under `check` it names every stale kind and the rows that differ, and
/// returns `Ok(true)`; otherwise it rewrites the pages.
pub fn run_kind_contracts(check: bool) -> std::io::Result<bool> {
    let registry = crate::kinds::production_registry();
    let mut stale = false;
    for name in registry.names() {
        let Some(kind) = registry.get(name) else { continue };
        let path = std::path::PathBuf::from(format!("docs/kinds/{name}.md"));
        let Ok(current) = std::fs::read_to_string(&path) else { continue };
        let contract = kind.contract();
        let spliced = crate::kinds::contract::splice_doc_block(&current, &contract.render_doc_block());
        if current == spliced {
            continue;
        }
        if check {
            stale = true;
            let committed: HashSet<&str> = current.lines().collect();
            let mut named = false;
            for row in contract.doc_rows() {
                if !committed.contains(row.as_str()) {
                    eprintln!("kind-contract-doc-check: kind={name}: row differs or is missing: {row}");
                    named = true;
                }
            }
            if !named {
                eprintln!("kind-contract-doc-check: kind={name}: ## Contract block is stale ({})", path.display());
            }
        } else {
            std::fs::write(&path, spliced)?;
        }
    }
    Ok(stale)
}

/// PRD-mcphost-kind-docs-from-registry R3: `<root>/docs/kinds/*.md`
/// basenames must equal the registered kind names. Every violation is
/// returned, each naming the kind or the page.
pub fn check_kind_page_set(root: &Path, kinds: &KindRegistry) -> Result<(), Vec<String>> {
    let mut pages: Vec<String> = Vec::new();
    if let Ok(entries) = std::fs::read_dir(root.join(KIND_PAGES_DIR)) {
        for entry in entries.flatten() {
            let file = entry.file_name().to_string_lossy().into_owned();
            if let Some(stem) = file.strip_suffix(".md") {
                pages.push(stem.to_string());
            }
        }
    }
    pages.sort();
    let names = kinds.names();
    let mut problems = Vec::new();
    for name in &names {
        if !pages.iter().any(|p| p == name) {
            problems.push(format!("kind `{name}` has no page {KIND_PAGES_DIR}/{name}.md"));
        }
    }
    for page in &pages {
        if !names.contains(&page.as_str()) {
            problems.push(format!("page {KIND_PAGES_DIR}/{page}.md names no registered kind `{page}`"));
        }
    }
    if problems.is_empty() { Ok(()) } else { Err(problems) }
}

#[cfg(test)]
mod tests {
    use super::*;

    /// AC4: `docs/plans.md` is byte-identical to a fresh render over
    /// `default_catalog()` -- the hermetic half of AC4 (the live half,
    /// "`/plans.json` equals the `billing.plans` tool output", is
    /// `tests/support_ac04_plans_doc_and_json_consistent.rs`, which needs a
    /// running server).
    #[test]
    fn committed_plans_doc_matches_a_fresh_render() {
        let committed = include_str!("../docs/plans.md");
        let fresh = render_plans_markdown(&PlanCatalog::default_catalog());
        assert_eq!(
            committed, fresh,
            "docs/plans.md has drifted from PlanCatalog::default_catalog() -- run `mcphost gen-docs`"
        );
    }

    /// AC4's other half: `www/plans.html` is byte-identical to a fresh
    /// render of [`render_plans_html`] -- deleting or hand-editing the
    /// generation step fails this the same way a `docs/plans.md` drift
    /// does above.
    #[test]
    fn committed_plans_html_matches_a_fresh_render() {
        let committed = include_str!("../www/plans.html");
        let fresh = render_plans_html();
        assert_eq!(committed, fresh, "www/plans.html has drifted -- run `mcphost gen-docs`");
    }

    /// PRD-mcphost-blob-virus-and-type-guard R8: `docs/blob-types.md` is
    /// byte-identical to a fresh render of `BLOB_TYPES`.
    #[test]
    fn committed_blob_types_doc_matches_a_fresh_render() {
        let committed = include_str!("../docs/blob-types.md");
        assert_eq!(committed, render_blob_types_doc(), "docs/blob-types.md has drifted -- run `mcphost gen-docs`");
    }

    /// PRD-mcphost-index-create-from-sources R2: `docs/retrieval.md` is
    /// byte-identical to a fresh render over `IndexSourceKind`.
    #[test]
    fn committed_retrieval_doc_matches_a_fresh_render() {
        let committed = include_str!("../docs/retrieval.md");
        assert_eq!(
            committed,
            crate::index::render_retrieval_doc(),
            "docs/retrieval.md has drifted -- run `mcphost gen-docs`"
        );
    }

    /// PRD-mcphost-tool-naming-convention-and-aliases AC4's own hermetic
    /// half: `docs/tools.md` byte-identical to a fresh render.
    #[test]
    fn committed_tools_doc_matches_a_fresh_render() {
        let committed = include_str!("../docs/tools.md");
        let fresh = render_tools_markdown(&KindRegistry::with_builtin());
        assert_eq!(
            committed, fresh,
            "docs/tools.md has drifted from the live registry -- run `mcphost gen-docs`"
        );
    }
}
